head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
scwin.vScrenID = "ULDBNS05000.xml";
scwin.vSelObj;
scwin.processGp;
scwin.vRowCount = 0;
scwin.vIsurCd, scwin.vBndClssCd, scwin.vBndInstCd, scwin.vSaleInstId;
scwin.vRowPos = 0;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : fn_Search
 * 설명       : 매출기관을 조회한다.
 ***********************************************/
scwin.fn_Search = function() {
    var param = '';
    param += "&{P}V_BND_CLSS_CD=" + $c.stf.getObjectValue(cmb_BndClssCd1);
    param += "&{P}V_BND_INST_CD=" + $c.stf.getObjectValue(cmb_BndInstCd1);
    var dsNm = 'BNS_PACK_SALE_INST';
    var qryId = 'lds.stf.bnspack.select.listSaleInst';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_List, dsNm, qryId, param);
    $c.cm.ShowWin(grd_List);
};


/********************************************** 
 * 함수명   : fn_Update
 * 설명       : 매출기관을 수정한다.
 ***********************************************/
scwin.fn_Update = function() {
    if (!scwin.fn_CheckData()) return;
    if (!window.confirm($c.stf.getMessageParam("MSG-A006", "수정"))) return;
    var url = "/bns/SaleInstMgt.do?method=update";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    var param = "ORG_ISUR_CD=" + scwin.vIsurCd;
    param += ", ORG_BND_INST_CD=" + scwin.vBndInstCd;
    param += ", ORG_BND_CLSS_CD=" + scwin.vBndClssCd;
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_SaleInst)";
    trs_Save.Parameters = param;
    trs_Save.Post();
};


/********************************************** 
 * 함수명   : fn_Update
 * 설명       : 비밀번호 초기화 처리한다.
 ***********************************************/
scwin.fn_PwdInit = function() {
    if (!window.confirm($c.stf.getMessageParam("MSG-A006", "비밀번호 초기화") + "\n\n비밀번호는 아이디와 동일하게 초기화됩니다.")) return;
    var url = "/bns/SaleInstMgt.do?method=processPwdInit";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    var param = "";
    dts_SaleInst.UseChangeInfo = "False";
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_SaleInst)";
    trs_Save.Parameters = param;
    trs_Save.Post();
};


/********************************************** 
 * 함수명   : fn_Delete
 * 설명       : 매출기관을 삭제한다.
 ***********************************************/
scwin.fn_Delete = function() {
    if (!window.confirm($c.stf.getMessageParam("MSG-A006", "삭제"))) return;
    var url = "/bns/SaleInstMgt.do?method=delete";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
    var param = "ISUR_CD=" + scwin.vIsurCd;
    param += ", BND_INST_CD=" + scwin.vBndInstCd;
    param += ", BND_CLSS_CD=" + scwin.vBndClssCd;
    param += ", SALE_INST_ID=" + scwin.vSaleInstId;
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_SaleInst)";
    trs_Save.Parameters = param;
    trs_Save.Post();
};


/********************************************** 
 * 함수명   : fn_Create
 * 설명       : 매출기관을 생성한다.
 ***********************************************/
scwin.fn_Create = function() {
    if (!scwin.fn_CheckData()) return;
    if (!window.confirm($c.stf.getMessageParam("MSG-A006", "신규등록"))) return;
    var url = "/bns/SaleInstMgt.do?method=createNew";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_SaleInst)";
    //trs_Save.Parameters = param;
    trs_Save.Post();
};


/********************************************** 
 * 함수명   : fn_CheckData
 * 설명       : 입력데이터를 체크한다.
 ***********************************************/
scwin.fn_CheckData = function() {
    if ($c.stf.getObjectValue(cmb_BndClssCd) == '') {
        $c.win.alert("채권분류를 선택하셔야 합니다.");
        return false;
    }
    if ($c.stf.getObjectValue(cmb_IsurCd) == '') {
        $c.win.alert("발행기관을 선택하셔야 합니다.");
        return false;
    }
    if ($c.stf.getObjectValue(cmb_BndInstCd) == '') {
        $c.win.alert("매출기관을 선택하셔야 합니다.");
        return false;
    }
    if ($c.stf.getObjectValue(txb_BrnNm) == '') {
        $c.win.alert("지점명을 입력해 주세요.");
        return false;
    }
    //자리수 체크
    if (!$c.stf.checkMaxLength(txb_BrnNm, 80, '매출기관 지점명')) return false;
    if (!$c.stf.checkMaxLength(txb_ChrgNm, 80, '담당자명')) return false;

    //등록이면
    if (scwin.processGp == SCREN_PROCS_TP_CD_02) {
        //중복체크
        var param = '';
        param += "&{P}V_BND_CLSS_CD=" + $c.stf.getObjectValue(cmb_BndClssCd);
        param += "&{P}V_ISUR_CD=" + $c.stf.getObjectValue(cmb_IsurCd);
        param += "&{P}V_BND_INST_CD=" + $c.stf.getObjectValue(cmb_BndInstCd);
        var dsNm = 'BNS_PACK_SALE_INST_CHK';
        var qryId = 'lds.stf.bnspack.select.listSaleInstCheck';
        $c.bns.fn_SearchBns(scwin.vScrenID, dts_Checker, dsNm, qryId, param);
        if (dts_Checker.getTotalRow() > 0) {
            $c.win.alert('이미 등록된 코드가 있습니다.');
            return false;
        }
    }
    return true;
};


/********************************************** 
 * 함수명   : fn_GetParInst
 * 설명       : 기관 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParInst = function(arrPar) {
    arrPar[0] = {
        INST_CD: $c.stf.getObjectValue(scwin.vSelObj),
        INST_NM: $c.stf.getObjectValue(scwin.vSelObj),
        LBL_NM: '',
        INIT_TP_CD: ''
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetParInst
 * 설명       : 기관 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParInst = function(arrPar) {
    var cbdata = "^ ," + arrPar[0].INST_CD + "^" + arrPar[0].INST_NM;
    scwin.vSelObj.CBData = cbdata;
    $c.stf.setObjectValue(scwin.vSelObj, arrPar[0].INST_CD);
};


/********************************************** 
 * 함수명   : fn_GetParBndClss
 * 설명       : 채권분류 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParBndClss = function(arrPar) {
    arrPar[0] = {
        BND_CLSS_CD: '',
        BND_TP_NM: ''
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetParBndClss
 * 설명       : 채권분류 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParBndClss = function(arrPar) {
    var cbdata = "^ ," + arrPar[0].BND_CLSS_CD + "^" + arrPar[0].BND_TP_NM;
    scwin.vSelObj.CBData = cbdata;
    $c.stf.setObjectValue(scwin.vSelObj, arrPar[0].BND_CLSS_CD);
};


/********************************************** 
 * 함수명   : fn_GetParIsurCd
 * 설명       : 발행기관 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParIsurCd = function(arrPar) {
    arrPar[0] = {
        ISUR_CD: $c.stf.getObjectValue(cmb_IsurCd),
        ISUR_NM: $c.stf.getObjectValue(cmb_IsurCd)
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetParIsurCd
 * 설명       : 발행기관 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParIsurCd = function(arrPar) {
    var cbdata = "^ ," + arrPar[0].ISUR_CD + "^" + arrPar[0].ISUR_NM;
    scwin.vSelObj.CBData = cbdata;
    $c.stf.setObjectValue(scwin.vSelObj, arrPar[0].ISUR_CD);
};


/********************************************** 
 * 함수명   : fn_ShowBndClss
 * 설명       : 채권분류 팝업을 보여준다.
 ***********************************************/
scwin.fn_ShowBndClss = function(selObj) {
    scwin.vSelObj = selObj;
    fn_GetPar = fn_GetParBndClss;
    fn_SetPar = fn_SetParBndClss;
    $c.bns.fn_PopBndClssCdSearch(selObj);
};


/********************************************** 
 * 함수명   : fn_ShowInst
 * 설명       : 기관 팝업을 보여준다.
 ***********************************************/
scwin.fn_ShowInst = function(selObj) {
    scwin.vSelObj = selObj;
    fn_GetPar = fn_GetParInst;
    fn_SetPar = fn_SetParInst;
    $c.bns.fn_PopInstSearch(selObj);
};


/********************************************** 
 * 함수명   : fn_SetCombo
 * 설명       : 콤보데이터를 설정한다.
 ***********************************************/
scwin.fn_SetCombo = function(selObj, cd, val) {
    scwin.vSelObj = selObj;
    var cbdata = "^ ," + cd + "^" + val;
    scwin.vSelObj.CBData = cbdata;
    $c.stf.setObjectValue(scwin.vSelObj, cd);
};


/********************************************** 
 * 함수명   : fn_initBtn
 * 설명       : 버튼을 초기화 한다.
 ***********************************************/
scwin.fn_initBtn = function() {
    btn_Create.src = "../img/bns/btn_40.gif";
    btn_Create.setDisabled("");
    btn_Init.src = "../img/bns/btn_new_nd.gif";
    btn_Init.setDisabled("disabled");
    btn_Update.setDisabled("disabled");
    btn_Update.src = "../img/bns/btn_modify_nd.gif";
    btn_Delete.setDisabled("disabled");
    btn_Delete.src = "../img/bns/btn_delete_nd.gif";
    btn_PwdInit.setDisabled("disabled");
    btn_PwdInit.src = "../img/bns/btn_32_d.gif";
};
scwin.gform_onload = function() {
    //숨기기
    $c.stf.showObj(txb_EncrypChrgPw, false);

    //패널라운드처리
    $c.bns.BnsPanelToGroupBox(pnl_Search);
    $c.bns.BnsPanelToGroupBox(pnl_Detail);

    //버튼초기화	
    scwin.fn_initBtn();

    //매출기관정보 데이터셋 정의
    dts_SaleInst.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=BNS_PACK_SALE_INST";
    dts_SaleInst.Reset();
    dts_SaleInst.insertRow();

    //목록조회
    scwin.fn_Search();
};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search();
};
scwin.img_BndClssCd1_onclick = function() {
    scwin.fn_ShowBndClss(cmb_BndClssCd1);
};
scwin.img_BndInstCd1_onclick = function() {
    scwin.fn_ShowInst(cmb_BndInstCd1);
};
scwin.img_BndClssCd_onclick = function() {
    scwin.fn_ShowBndClss(cmb_BndClssCd);
};
scwin.img_BndInstCd_onclick = function() {
    scwin.fn_ShowInst(cmb_BndInstCd);
};
scwin.img_IsurCd_onclick = function() {
    scwin.vSelObj = cmb_IsurCd;
    fn_GetPar = fn_GetParIsurCd;
    fn_SetPar = fn_SetParIsurCd;
    $c.bns.fn_PopIsurSearch(img_IsurCd);
};
scwin.dts_List_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_List);
    scwin.vRowCount = rowcount;
    txb_TotalCnt.setValue("총 " + rowcount + "건");
    //해당 ROW로 이동
    if (rowcount > 0) {
        $c.bns.fn_RowPos(dts_List, scwin.vRowPos);
    }
};
scwin.dts_List_OnRowPosChanged = function(row) {
    if (row > 0) {
        scwin.vRowPos = dts_List.getRowPosition();

        //버튼초기화
        btn_Create.src = "../img/bns/btn_40_d.gif";
        btn_Create.setDisabled("disabled");
        btn_Init.src = "../img/bns/btn_new_n.gif";
        btn_Init.setDisabled("");
        btn_Update.src = "../img/bns/btn_modify_n.gif";
        btn_Update.setDisabled("");
        btn_Delete.src = '../img/bns/btn_delete_n.gif';
        btn_Delete.setDisabled("");
        btn_PwdInit.setDisabled("");
        btn_PwdInit.src = "../img/bns/btn_32.gif";

        //수정 키값 설정
        scwin.vIsurCd = dts_List.getCellData(dts_List.getRowPosition(), "ISUR_CD");
        scwin.vBndInstCd = dts_List.getCellData(dts_List.getRowPosition(), "BND_INST_CD");
        scwin.vBndClssCd = dts_List.getCellData(dts_List.getRowPosition(), "BND_CLSS_CD");
        scwin.vSaleInstId = dts_List.getCellData(dts_List.getRowPosition(), "SALE_INST_ID");

        //데이터복제
        for (var i = 1; i <= dts_SaleInst.getTotalCol(); i++) {
            dts_SaleInst.setCellData(dts_SaleInst.getRowPosition(), dts_SaleInst.getColumnID(i - 1));
            //alert('aa='+i + ' ' + dts_SaleInst.ColumnID(i) + ' ' + dts_List.NameString(dts_List.RowPosition, dts_SaleInst.ColumnID(i)) );

        }

        //채권분류
        scwin.fn_SetCombo(cmb_BndClssCd, dts_SaleInst.getCellData(1, "BND_CLSS_CD"), dts_SaleInst.getCellData(1, "BND_CLSS_NM"));
        //매출기관
        scwin.fn_SetCombo(cmb_BndInstCd, dts_SaleInst.getCellData(1, "BND_INST_CD"), dts_SaleInst.getCellData(1, "INST_NM"));
        //발행기관
        scwin.fn_SetCombo(cmb_IsurCd, dts_SaleInst.getCellData(1, "ISUR_CD"), dts_SaleInst.getCellData(1, "ISUR_NM"));
    }
};
scwin.btn_Init_onclick = function() {
    //목록 위치 설정
    dts_List.setRowPosition(0, 0);
    //상세초기화
    dts_SaleInst.removeAll();
    dts_SaleInst.insertRow();
    //콤보초기화
    cmb_BndClssCd.ClearData();
    cmb_BndInstCd.ClearData();
    cmb_IsurCd.ClearData();
    //버튼초기화
    scwin.fn_initBtn();
};
scwin.trs_Save_OnFail = function() {
    if (scwin.processGp == SCREN_PROCS_TP_CD_02) {
        $c.win.alert($c.stf.getMessageParam("MSG-A002", "신규등록"));
    }
    if (scwin.processGp == SCREN_PROCS_TP_CD_03) {
        $c.win.alert($c.stf.getMessageParam("MSG-A002", "수정"));
    }
    if (scwin.processGp == SCREN_PROCS_TP_CD_04) {
        $c.win.alert($c.stf.getMessageParam("MSG-A002", "삭제"));
    }
};
scwin.trs_Save_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0001"));
    //상세초기화
    dts_SaleInst.removeAll();
    dts_SaleInst.insertRow();
    //콤보초기화
    cmb_BndClssCd.ClearData();
    cmb_BndInstCd.ClearData();
    cmb_IsurCd.ClearData();
    //버튼초기화
    scwin.fn_initBtn();
    scwin.fn_Search();
};
scwin.btn_Update_onclick = function() {
    if (scwin.vRowCount == 0) return;
    scwin.processGp = SCREN_PROCS_TP_CD_03;
    scwin.fn_Update();
};
scwin.btn_Delete_onclick = function() {
    if (scwin.vRowCount == 0) return;
    scwin.processGp = SCREN_PROCS_TP_CD_04;
    scwin.fn_Delete();
};
scwin.btn_Create_onclick = function() {
    scwin.processGp = SCREN_PROCS_TP_CD_02;
    scwin.fn_Create();
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07, '');
    var fileNm = $c.session.getExcelDownPath() + $c.ut.cGetToday("yyyymmddhhmmss") + "_매출기관관리.xls";
    $c.data.downloadGridViewExcel(grd_List, "매출기관관리", "", "8");
};
scwin.btn_PwdInit_onclick = function() {
    scwin.fn_PwdInit();
};
